CAMPI_ASSET = ["status", "reparto", "assigned_legacy_user_id", "assignment_to", "assignment_reparto", "assignment_location"]
CAMPI_ENDPOINT = ["endpoint_name", "ip", "vlan", "switch_name", "switch_port", "punto"]


def _testo(value):
    return "" if value is None else str(value).strip()


def baseline(apps, schema_editor):
    """Primo punto di storico: lo stato attuale con fonte "baseline", senza inventare cronologia."""
    Asset = apps.get_model("assets", "Asset")
    Endpoint = apps.get_model("assets", "AssetEndpoint")
    History = apps.get_model("assets", "AssetFieldHistory")
    db = schema_editor.connection.alias
    ora = django.utils.timezone.now()
    righe = []

    def flush(force=False):
        if righe and (force or len(righe) >= 500):
            History.objects.using(db).bulk_create(righe, batch_size=200)
            righe.clear()

    def riga(asset_id, campo, valore, endpoint_id=None, label=""):
        righe.append(History(asset_id=asset_id, campo=campo, valore_prima="", valore_dopo=valore,
                             endpoint_id=endpoint_id, endpoint_label=label[:255], fonte="baseline",
                             dettaglio="Stato al rilascio dello storico", cambiato_il=ora))
        flush()

    def pagine(qs, campi):
        # Pagine per pk, liste materializzate: su SQL Server (senza MARS) un cursore
        # aperto mentre si fanno gli INSERT blocca la connessione.
        ultimo = 0
        while True:
            pagina = list(qs.filter(pk__gt=ultimo).order_by("pk").values("id", *campi)[:1000])
            if not pagina:
                return
            yield from pagina
            ultimo = pagina[-1]["id"]

    for row in pagine(Asset.objects.using(db), CAMPI_ASSET):
        for campo in CAMPI_ASSET:
            valore = _testo(row[campo])
            if valore:
                riga(row["id"], campo, valore)
    for row in pagine(Endpoint.objects.using(db), ["asset_id", *CAMPI_ENDPOINT]):
        label = " · ".join(x for x in (_testo(row["endpoint_name"]), _testo(row["ip"]),
                                       f"VLAN {row['vlan']}" if row["vlan"] else "") if x)
        riga(row["asset_id"], "endpoint", "presente", row["id"], label)
        for campo in CAMPI_ENDPOINT:
            valore = _testo(row[campo])
            if valore:
                riga(row["asset_id"], f"endpoint.{campo}", valore, row["id"], label)
    flush(force=True)


